			m.put("sharesHousehold", true);
			if (i == 2) {
				m.put("email", uniqueEmail());
			}
			last = createOwnerOk(m);
		}
		getOwner(last).andExpect(jsonPath("$.membershipLevel").value(3)); // 5 points, zero tenure -> not 4
	}
}
