245	    /**
246	     * Derives an owner's uncapped numeric membership level directly from its
247	     * {@link #membershipPoints(Owner) membership points}, before the household level cap is applied.
248	     *
249	     * @param owner the owner to derive the points-based membership level for
250	     * @return the points-based membership level, between {@code 1} and {@code 4}
251	     */
252	    private Integer pointsMembershipLevel(Owner owner) {
253	        int points = membershipPoints(owner);
